func TestDashFM_RequirementQuality_FieldNamesAndHardcodedPaging(t *testing.T) {
    setupDashFMEA(t)
    gin.SetMode(gin.TestMode)
    r := gin.New()
    h := handler.NewDashboardHandler()
    r.GET("/metrics/requirement-quality/filter-options", h.RequirementQualityFilterOptions)
    r.POST("/metrics/requirement-quality/list", h.RequirementQualityList)
    r.POST("/metrics/requirement-quality/overview", h.RequirementQualityOverview)

    call := func(method, target, body string) map[string]interface{} {
        req := httptest.NewRequest(method, target, bytes.NewBufferString(body))
        if body != "" {
            req.Header.Set("Content-Type", "application/json")
        }
        w := httptest.NewRecorder()
        r.ServeHTTP(w, req)
        var env dashFMEAEnvelope
        if err := json.Unmarshal(w.Body.Bytes(), &env); err != nil {
            t.Fatalf("响应不是 {code,data,message} 契约结构: %v body=%s", err, w.Body.String())
        }
        var data map[string]interface{}
        if err := json.Unmarshal(env.Data, &data); err != nil {
            t.Fatalf("data 不是对象: %v data=%s", err, env.Data)
        }
        return data
    }

    opts := call(http.MethodGet, "/metrics/requirement-quality/filter-options", "")
    for _, key := range []string{"projectOptions", "requirementOptions", "statusOptions"} {
        if _, ok := opts[key]; !ok {
            t.Errorf("filter-options 缺少前端契约字段 %q，实际 keys=%v", key, dashFMEAKeys(opts))
        }
    }

    listData := call(http.MethodPost, "/metrics/requirement-quality/list", `{"current":4,"pageSize":50}`)
    if listData["current"] != float64(4) || listData["pageSize"] != float64(50) {
        t.Errorf("分页元数据未回显请求值：期望 current=4/pageSize=50，实际 current=%v pageSize=%v", listData["current"], listData["pageSize"])
    }

    ov := call(http.MethodPost, "/metrics/requirement-quality/overview", `{"current":1,"pageSize":1}`)
    if _, ok := ov["requirementTotal"]; !ok {
        t.Errorf("overview 缺少前端契约字段 requirementTotal，实际 keys=%v", dashFMEAKeys(ov))
    }
    if ov["passRate"] == float64(100) {
        t.Errorf("空库概览仍返回 passRate=100（硬编码常量），对前端是虚假绿灯")
    }

    full := router.SetupRouter()
    w := httptest.NewRecorder()
    full.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/metrics/requirement-quality/story-search?keyword=abc", nil))
    if w.Code != http.StatusOK {
        t.Errorf("期望 story-search 可用，实际 HTTP %d body=%s", w.Code, w.Body.String())
    }
    if !json.Valid(w.Body.Bytes()) {
        t.Errorf("story-search 返回非 JSON，破坏统一响应外壳，body=%s", w.Body.String())
    }
}

