)

type menuFMEAEnvelope struct {
    Code    int             `json:"code"`
    Data    json.RawMessage `json:"data"`
    Message string          `json:"message"`
}

// menuFMEANode 对应 model.SysMenu 的树形 JSON
type menuFMEANode struct {
    ID         int64           `json:"id"`
    ParentID   int64           `json:"parentId"`
    MenuKey    string          `json:"menuKey"`
    Title      string          `json:"title"`
    Permission string          `json:"permission"`
    Status     string          `json:"status"`
    IsHidden   int             `json:"isHidden"`
    Children   []*menuFMEANode `json:"children"`
}

// setupMenuFMEA 使用独立库 anubis_fmea_test，并清空 sys_menu/user/operation_log
func setupMenuFMEA(t *testing.T) *gorm.DB {
    t.Helper()
    dsn := os.Getenv("TEST_MYSQL_DSN")
    if dsn == "" {
        dsn = "root:root@tcp(127.0.0.1:3307)/"
    }
    admin, err := gorm.Open(mysql.Open(dsn+"?charset=utf8mb4&parseTime=true&loc=Local"), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
    if err != nil {
        t.Skipf("MySQL 测试实例不可用，跳过: %v", err)
    }
    if err := admin.Exec("CREATE DATABASE IF NOT EXISTS anubis_fmea_test DEFAULT CHARSET utf8mb4").Error; err != nil {
        t.Skipf("无法创建测试库，跳过: %v", err)
    }
    db, err := gorm.Open(mysql.Open(dsn+"anubis_fmea_test?charset=utf8mb4&parseTime=true&loc=Local"), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
    if err != nil {
        t.Fatalf("连接测试库失败: %v", err)
    }
    if err := db.AutoMigrate(&model.SysMenu{}, &model.User{}, &model.UserRole{}, &model.UserRoleRelation{}, &model.UserRolePermission{}, &model.OperationLog{}); err != nil {
        t.Fatalf("AutoMigrate 失败: %v", err)
    }
    for _, m := range []interface{}{&model.SysMenu{}, &model.User{}, &model.UserRole{}, &model.UserRoleRelation{}, &model.UserRolePermission{}, &model.OperationLog{}} {
        if err := db.Session(&gorm.Session{AllowGlobalUpdate: true}).Unscoped().Delete(m).Error; err != nil {
            t.Fatalf("清理测试数据失败: %v", err)
        }
    }
    config.DB = db
    return db
}

func flattenMenuFMEAKeys(nodes []*menuFMEANode) []string {
    keys := make([]string, 0, len(nodes))
    for _, n := range nodes {
        if n == nil {
            continue
        }
        keys = append(keys, n.MenuKey)
        keys = append(keys, flattenMenuFMEAKeys(n.Children)...)
    }
    return keys
}

func containsMenuFMEAKey(keys []string, want string) bool {
    for _, k := range keys {
        if k == want {
            return true
        }
    }
    return false
}

func TestMenuFM_GetMenuTree_EmptyTableMarshalsToNull(t *testing.T) {
    setupMenuFMEA(t)
    gin.SetMode(gin.TestMode)
    r := gin.New()
    r.GET("/system/menu/tree", handler.NewMenuHandler().GetMenuTree)

    w := httptest.NewRecorder()
    r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/system/menu/tree", nil))

    var env menuFMEAEnvelope
    if err := json.Unmarshal(w.Body.Bytes(), &env); err != nil {
        t.Fatalf("解析响应失败: %v body=%s", err, w.Body.String())
    }
    if env.Code != 200 {
        t.Fatalf("期望 code=200，实际 %d message=%s", env.Code, env.Message)
    }
    if string(env.Data) != "[]" {
        t.Errorf("buildMenuTree 返回 nil slice，期望 data 为 []（前端 Array.isArray/直接 .map 会崩），实际 %s", env.Data)
    }
}

