func TestMenuFM_BuildMenuTree_OrphanParentIdSilentlyDropped(t *testing.T) {
    db := setupMenuFMEA(t)
    if err := db.Create(&[]model.SysMenu{
        {ID: 10, ParentID: 0, MenuKey: "root-ok", Title: "正常根菜单", Status: "ENABLE", MenuType: "MENU"},
        {ID: 11, ParentID: 999, MenuKey: "orphan", Title: "孤儿菜单", Status: "ENABLE", MenuType: "MENU"},
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }

    gin.SetMode(gin.TestMode)
    r := gin.New()
    r.GET("/system/menu/tree", handler.NewMenuHandler().GetMenuTree)

    w := httptest.NewRecorder()
    r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/system/menu/tree", nil))
    var env menuFMEAEnvelope
    if err := json.Unmarshal(w.Body.Bytes(), &env); err != nil {
        t.Fatalf("解析响应失败: %v body=%s", err, w.Body.String())
    }
    var tree []*menuFMEANode
    if err := json.Unmarshal(env.Data, &tree); err != nil {
        t.Fatalf("data 不是菜单树数组: %v data=%s", err, env.Data)
    }
    keys := flattenMenuFMEAKeys(tree)

    if !containsMenuFMEAKey(keys, "orphan") {
        t.Errorf("parentId=999 不存在的菜单被静默丢弃（期望出现在树中或写入时被拒绝），实际树 keys=%v", keys)
    }

    var cnt int64
    if err := db.Model(&model.SysMenu{}).Where("menu_key = ?", "orphan").Count(&cnt).Error; err != nil {
        t.Fatalf("回查失败: %v", err)
    }
    if cnt != 1 {
        t.Fatalf("前置条件失败：孤儿菜单应已落库，实际 %d 条", cnt)
    }
    if !containsMenuFMEAKey(keys, "root-ok") {
        t.Errorf("正常根菜单应出现在树中，实际树 keys=%v", keys)
    }
}

