func TestMenuFM_UserMenuTree_UnknownTokenGetsAdminMenus(t *testing.T) {
    db := setupMenuFMEA(t)
    if err := db.Create(&[]model.User{
        {ID: "admin", Name: "Administrator", Deleted: model.BitBool(false), Enable: model.BitBool(true)},
        {ID: "zz-lowpriv", Name: "普通用户", Deleted: model.BitBool(false), Enable: model.BitBool(true)},
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }
    if err := db.Create(&model.UserRoleRelation{ID: "rel-admin", UserID: "admin", RoleID: "admin", SourceID: "system"}).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }
    if err := db.Create(&[]model.SysMenu{
        {ID: 1, ParentID: 0, MenuKey: "workspace", Title: "工作台", Permission: "WORKSPACE:READ", Status: "ENABLE", MenuType: "MENU"},
        {ID: 2, ParentID: 0, MenuKey: "system-setting", Title: "系统设置", Permission: "SYSTEM:WRITE", Status: "ENABLE", MenuType: "MENU"},
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }

    gin.SetMode(gin.TestMode)
    r := gin.New()
    r.Use(middleware.AuthMiddleware())
    r.GET("/system/menu/user-tree", handler.NewMenuHandler().GetUserMenuTree)

    cases := []struct {
        name  string
        token string
    }{
        {name: "伪造任意 token", token: "totally-bogus-token"},
        {name: "完全不携带 token", token: ""},
    }
    for _, tc := range cases {
        req := httptest.NewRequest(http.MethodGet, "/system/menu/user-tree", nil)
        if tc.token != "" {
            req.Header.Set("X-AUTH-TOKEN", tc.token)
        }
        w := httptest.NewRecorder()
        r.ServeHTTP(w, req)

        var env menuFMEAEnvelope
        if err := json.Unmarshal(w.Body.Bytes(), &env); err != nil {
            t.Fatalf("[%s] 响应不是 {code,data,message} 契约结构: %v body=%s", tc.name, err, w.Body.String())
        }
        if env.Code == 200 && string(env.Data) != "[]" {
            var tree []*menuFMEANode
            if err := json.Unmarshal(env.Data, &tree); err != nil {
                t.Fatalf("[%s] data 不是菜单树: %v data=%s", tc.name, err, env.Data)
            }
            if containsMenuFMEAKey(flattenMenuFMEAKeys(tree), "system-setting") {
                t.Errorf("[%s] 匿名/伪造凭据获得了需要 SYSTEM:WRITE 的菜单（鉴权绕过），实际树 keys=%v", tc.name, flattenMenuFMEAKeys(tree))
            }
        }
    }
}

