    if err := db.Create(&[]model.SysMenu{
        {ID: 20, ParentID: 0, MenuKey: "l1", Title: "一级", Status: "ENABLE", MenuType: "MENU", CreateTime: now, UpdateTime: now},
        {ID: 21, ParentID: 20, MenuKey: "l2-disabled", Title: "二级停用", Status: "DISABLE", MenuType: "DIRECTORY", CreateTime: now, UpdateTime: now},
        {ID: 22, ParentID: 21, MenuKey: "l3-enabled", Title: "三级启用", Status: "ENABLE", MenuType: "MENU", CreateTime: now, UpdateTime: now},
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }

    gin.SetMode(gin.TestMode)
    r := gin.New()
    r.GET("/system/menu/user-tree", handler.NewMenuHandler().GetUserMenuTree)

    w := httptest.NewRecorder()
    r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/system/menu/user-tree", nil))
    var env menuFMEAEnvelope
    if err := json.Unmarshal(w.Body.Bytes(), &env); err != nil {
        t.Fatalf("解析响应失败: %v body=%s", err, w.Body.String())
    }

    var cnt int64
    if err := db.Model(&model.SysMenu{}).Where("status = ?", "ENABLE").Count(&cnt).Error; err != nil {
        t.Fatalf("回查失败: %v", err)
    }
    if cnt != 2 {
        t.Fatalf("前置条件失败：应存在 2 个 ENABLE 菜单，实际 %d", cnt)
    }

    var tree []*menuFMEANode
    if err := json.Unmarshal(env.Data, &tree); err != nil {
        t.Fatalf("data 不是菜单树: %v data=%s", err, env.Data)
    }
    keys := flattenMenuFMEAKeys(tree)
    if !containsMenuFMEAKey(keys, "l3-enabled") {
        t.Errorf("ENABLE 的三级菜单因父节点 DISABLE 被 buildMenuTree 静默丢弃（期望其仍可达或至少返回告警），实际树 keys=%v", keys)
    }
    if !containsMenuFMEAKey(keys, "l1") {
        t.Errorf("一级 ENABLE 菜单应出现在树中，实际树 keys=%v", keys)
    }
}

