func TestMenuFM_UpdateMenu_PartialBodyZeroesStatusAndHidesMenu(t *testing.T) {
    db := setupMenuFMEA(t)
    if err := db.Create(&model.SysMenu{
        ID: 1, ParentID: 0, MenuKey: "setting", Title: "系统设置", Path: "/setting",
        Icon: "Settings", Permission: "SYSTEM:READ", MenuType: "MENU", Sort: 99, Status: "ENABLE",
        CreateTime: time.Now().UnixMilli(), UpdateTime: time.Now().UnixMilli(),
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }

    gin.SetMode(gin.TestMode)
    r := gin.New()
    r.POST("/system/menu/update", handler.NewMenuHandler().UpdateMenu)
    r.GET("/system/menu/user-tree", handler.NewMenuHandler().GetUserMenuTree)

    req := httptest.NewRequest(http.MethodPost, "/system/menu/update", bytes.NewBufferString(`{"id":1,"menuKey":"setting","title":"系统设置V2"}`))
    req.Header.Set("Content-Type", "application/json")
    w := httptest.NewRecorder()
    r.ServeHTTP(w, req)

    var env menuFMEAEnvelope
    if err := json.Unmarshal(w.Body.Bytes(), &env); err != nil {
        t.Fatalf("解析响应失败: %v body=%s", err, w.Body.String())
    }
    if env.Code != 200 {
        t.Fatalf("期望 code=200，实际 %d message=%s", env.Code, env.Message)
    }

    var after model.SysMenu
    if err := db.First(&after, 1).Error; err != nil {
        t.Fatalf("回查菜单失败: %v", err)
