func TestLogFM_QueryParams_EndTimeSecondsAndCountConsistency(t *testing.T) {
    db := setupLogFMEA(t)
    base := time.Now().UnixMilli()
    if err := db.Create(&[]model.OperationLog{
        {ID: 501, ProjectID: "p1", OrganizationID: "org-A", CreatedAt: base - 10000, CreateUser: "admin", Type: "ADD", Module: "SYSTEM", Content: "较早"},
        {ID: 502, ProjectID: "p1", OrganizationID: "org-A", CreatedAt: base - 5000, CreateUser: "admin", Type: "ADD", Module: "SYSTEM", Content: "中间"},
        {ID: 503, ProjectID: "p1", OrganizationID: "org-A", CreatedAt: base - 1000, CreateUser: "admin", Type: "ADD", Module: "SYSTEM", Content: "最新"},
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }

    gin.SetMode(gin.TestMode)
    r := gin.New()
    r.POST("/operation/log/list", handler.NewLogHandler().SystemLogList)

    call := func(body string) logFMEAPage {
        req := httptest.NewRequest(http.MethodPost, "/operation/log/list", bytes.NewBufferString(body))
        req.Header.Set("Content-Type", "application/json")
        w := httptest.NewRecorder()
        r.ServeHTTP(w, req)
        return newLogFMEAPage(t, w.Body.Bytes())
    }

    msWindow := call(fmt.Sprintf(`{"current":1,"pageSize":10,"startTime":%d,"endTime":%d}`, base-6000, base))
    if msWindow.Total != 2 {
        t.Fatalf("前置条件失败：毫秒时间窗应命中 2 条，实际 %d", msWindow.Total)
    }

    var dbCount int64
    if err := db.Model(&model.OperationLog{}).Where("created_at >= ? AND created_at <= ?", base-6000, base).Count(&dbCount).Error; err != nil {
        t.Fatalf("DB 计数失败: %v", err)
    }
    if msWindow.Total != dbCount {
        t.Errorf("响应 total=%d 与 SELECT COUNT(*)=%d 不一致（Count error 被忽略）", msWindow.Total, dbCount)
    }

    secondsWindow := call(fmt.Sprintf(`{"current":1,"pageSize":10,"startTime":%d,"endTime":%d}`, (base-6000)/1000, base/1000))
    if secondsWindow.Total != msWindow.Total {
        t.Errorf("endTime 使用秒级时间戳时 total=%d（毫秒为 %d）：秒被当作毫秒比较导致结果集静默为空", secondsWindow.Total, msWindow.Total)
    }
}

